import{_ as o,o as u,c as e,ag as a}from"./chunks/framework.CAXxHpAX.js";const d=JSON.parse('{"title":"金刚经7分-无为法而有差别","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经7分-无为法而有差别.md","filePath":"60-原文段落/金刚经7分-无为法而有差别.md","lastUpdated":null}'),_={name:"60-原文段落/金刚经7分-无为法而有差别.md"};function q(r,t,s,n,p,c){return u(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="金刚经7分-无为法而有差别" tabindex="-1">金刚经7分-无为法而有差别 <a class="header-anchor" href="#金刚经7分-无为法而有差别" aria-label="Permalink to &quot;金刚经7分-无为法而有差别&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/7了空居士讲《金刚经》-第七分无得无说分20161014">7了空居士讲《金刚经》-第七分无得无说分20161014</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>所以者何？一切贤圣皆以无为法而有差别。</strong></p><p>嗯，&quot;所以者何？&quot;就是说，这些我们说了这么多，说&quot;皆不可取，不可说，非法非非法&quot;，这么解释，解释这么多，然后就告诉我们：&quot;一切贤圣皆以无为法而有差别&quot;，就是这些开悟的人有智慧的人，他们为人处世啊，都是&quot;以无为法而有差别&quot;。这里最关键就是&quot;无为法&quot;。</p><p>什么是无为法？就是不妄为、不主观臆断、不武断啊。就是做什么事情，&quot;无为法&quot;，就是说不要有任何成见，你都要按照客观实际情况去&quot;差别&quot;，&quot;差别&quot;就是错落高低嘛，分门别类嘛，其实就是依实际情况去具体问题具体分析或者是去因地制宜啊，而不是教条主义或者什么照搬硬套等等本本主义啊等等，就不搞这些，这些就是搞来搞去都是不准的，一定要按照实际情况去分析去应用。</p><p>我曾经说过，六祖的一生，就是在示现《金刚经》的第十七品&quot;究竟无我分&quot;啊。&quot;究竟无我分&quot;说&quot;一切法皆是佛法&quot;。嗯，我了空居士的半生，不能说一生，因为从前我也不懂，从这个修炼以后，到...尤其是从现在开始吧，我都主要是给大家——不敢说示现——给大家讲解的内容，其实都是围绕着第七品&quot;无得无说分&quot;，也就是&quot;一切贤圣皆以无为法而有差别&quot;，我的下半生都是围绕着这个，可以说我的一切言行都是围绕了&quot;一切贤圣皆以无为法而有差别&quot;。</p>',7)])])}const i=o(_,[["render",q]]);export{d as __pageData,i as default};
